hp:equation.hp:script:
EQALIGN { □ rm "ABCD"
                                                                it&= triangle rm "ABD" it +
                                                                triangle rm "BCD" it # &= {1}
                                                                over {2} times bar {rm "AD" it}
                                                                times bar {rm "CD" it} + {1} over
                                                                {2} times bar {rm "BC" it} times bar
                                                                {rm "CD" it} # &= {1} over {2}
                                                                times x times 4+ {1} over {2} times
                                                                LEFT ( x+ {3} over {2} RIGHT ) times
                                                                4 # &=2x+ LEFT ( 2x+3 RIGHT ) #
                                                                &=4x+3=17 }

EQALIGN { LEFT LBRACE {4}
                                                                over {3} - LEFT ( - {1} over {3}
                                                                RIGHT ) RIGHT RBRACE div LEFT ( -
                                                                {1} over {9} RIGHT )&= {5} over
                                                                {3} times LEFT ( -9 RIGHT ) =- LEFT
                                                                ( {5} over {3} times 9 RIGHT ) #
                                                                &=-15 }

EQALIGN { &rm "가입비
                                                                    15000원" it # &rm "- 가입 시 추가
                                                                    요금 없이 무제한 편집 가능" it }

EQALIGN { {6} over {p} times
                                                                n+ {q} over {11}&= {6} over {99}
                                                                n+ {2} over {11} = {2} over {33} n+
                                                                {2} over {11} = {2n+6} over {33} #
                                                                &= {2 LEFT ( n+3 RIGHT )} over
                                                                {3 times 11} }

EQALIGN { □ rm "ACDB"
                                                                it&= triangle rm "CDB" it +
                                                                triangle rm "ACB" it # &= {1}
                                                                over {2} times bar {rm "CD" it}
                                                                times bar {rm "BH" it} + {1} over
                                                                {2} times bar {rm "AB" it} times bar
                                                                {rm "BH" it} # &= {1} over {2}
                                                                times {9} over {2} q times {p} over
                                                                {2} + {1} over {2} times 3q times
                                                                {p} over {2} = {15} over {8} pq }

EQALIGN { triangle rm "ABC"
                                                                it&= {1} over {2} times bar {rm
                                                                "BC" it} times bar {rm "CA" it}
                                                                times sin 60 DEG # &= {1} over
                                                                {2} times LEFT ( 5+x RIGHT ) times
                                                                LEFT ( x+2 RIGHT ) times {sqrt {3}}
                                                                over {2} # &= {sqrt {3}} over
                                                                {4} LEFT ( x+2 RIGHT ) LEFT ( x+5
                                                                RIGHT ) ~~ cdots cdots ㉡ }

triangle rm "ABC" it = {1}
                                                                over {2} times bar {rm "AB" it}
                                                                times bar {rm "BC" it} = {1} over
                                                                {2} times 10 times bar {rm "BC" it}
                                                                = # 30

T= {1} over {3} times pi
                                                                times 4^{2} times 10= {160} over {3}
                                                                pi

bar {rm "DC" it} ^{2}= bar
                                                                {rm "AC" it} times bar {rm "EC" it}
                                                                `

bar {rm "DC" it} ^{2}= bar
                                                                {rm "BD" it} ^{2}+ bar {rm "BC" it}
                                                                ^{2}=x^{2}+x^{2}=2x^{2}

LEFT ( sqrt {2} x RIGHT )
                                                                ^{2}= LEFT ( 5 times bar {rm "EC"
                                                                it} RIGHT ) times bar {rm "EC" it}

bar {rm "AB" it} ^{2}= bar
                                                                {rm "AC" it} ^{2}- bar {rm "BC" it}
                                                                ^{2}= LEFT ( sqrt {10} x RIGHT )
                                                                ^{2}-x^{2}=9x^{2}

triangle rm "ADC" it = {1}
                                                                over {2} times bar {rm "AD" it}
                                                                times bar {rm "BC" it} = {1} over
                                                                {2} times 2x times x=x^{2}

triangle rm "OCA" it = {1}
                                                                over {2} times bar {rm "OA" it `'}
                                                                times bar {rm "CH" it `'} = {5} over
                                                                {2} times bar {rm "CH" it `'} =5

bar {rm "HF" it} ^{2}= bar
                                                                {rm "HC" it} ^{2}- bar {rm "FC" it}
                                                                ^{2}=4^{2}-3^{2}=7

EQALIGN { bar {rm "CG" it}
                                                                ^{2}&= bar {rm "HC" it} ^{2}+
                                                                bar {rm "GH" it} ^{2} # &=4^{2}+
                                                                LEFT ( {4 sqrt {7}} over {7} RIGHT )
                                                                ^{2}= {128} over {7} }
